metrics.workdir_dsl:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses the book catalogue and places orders."
        bookshop = softwareSystem "Bookshop" "An online bookshop where customers browse the catalogue and order books." {
            webStore = container "Web Store" "The web application customers use to browse books and place orders." "Spring Boot"
            orderProcessor = container "Order Processor" "Validates and processes customer orders." "Java"
        }

        customer -> webStore "Browses the catalogue and places orders through" "HTTPS/HTML"
        webStore -> orderProcessor "Submits new orders to" "HTTP/JSON"
    }

    views {
        systemContext bookshop "SystemContext" "Shows the Bookshop system and the Customer who uses it." {
            include *
            autoLayout
        }
    }

    configuration {
        scope softwaresystem
    }
}
